-- Read-only reconciliation. Every violations count must be zero.
SELECT 'request_line_totals' check_name, COUNT(*) violations FROM purchase_requests h WHERE h.total_amount <> COALESCE((SELECT SUM(d.amount) FROM request_items d WHERE d.request_id=h.id),0)
UNION ALL SELECT 'quote_line_totals', COUNT(*) FROM quotes h WHERE h.total_amount <> COALESCE((SELECT SUM(d.amount) FROM quote_items d WHERE d.quote_id=h.id),0)
UNION ALL SELECT 'order_line_totals', COUNT(*) FROM purchase_orders h WHERE h.total_amount <> COALESCE((SELECT SUM(d.amount) FROM order_items d WHERE d.order_id=h.id),0)
UNION ALL SELECT 'receipt_line_totals', COUNT(*) FROM receipts h WHERE h.amount <> COALESCE((SELECT SUM(d.amount) FROM receipt_items d WHERE d.receipt_id=h.id),0)
UNION ALL SELECT 'receipt_order_quantity', COUNT(*) FROM order_items d WHERE d.received_quantity <> COALESCE((SELECT SUM(r.quantity) FROM receipt_items r WHERE r.order_item_id=d.id),0) OR d.received_quantity>d.quantity OR d.received_quantity<0
UNION ALL SELECT 'order_requires_approval', COUNT(*) FROM purchase_orders o JOIN purchase_requests r ON r.id=o.request_id WHERE r.status<>'APPROVED'
UNION ALL SELECT 'order_request_quantity', COUNT(*) FROM request_items r WHERE COALESCE((SELECT SUM(o.quantity) FROM order_items o WHERE o.request_item_id=r.id),0)>r.quantity
UNION ALL SELECT 'stock_quantity_flow', COUNT(*) FROM inventory i WHERE i.quantity <> COALESCE((SELECT SUM(m.quantity) FROM stock_movements m WHERE m.tenant_id=i.tenant_id AND m.warehouse_id=i.warehouse_id AND m.material_id=i.material_id),0)
UNION ALL SELECT 'stock_value_flow', COUNT(*) FROM inventory i WHERE i.stock_value <> COALESCE((SELECT SUM(CASE WHEN m.kind IN ('RECEIPT','ISSUE_RETURN','STOCKTAKE_GAIN') THEN m.amount ELSE -m.amount END) FROM stock_movements m WHERE m.tenant_id=i.tenant_id AND m.warehouse_id=i.warehouse_id AND m.material_id=i.material_id),0)
UNION ALL SELECT 'stock_nonnegative', COUNT(*) FROM inventory i WHERE i.quantity<0 OR i.stock_value<0 OR (i.quantity=0 AND i.stock_value<>0)
UNION ALL SELECT 'movement_has_inventory', COUNT(*) FROM stock_movements m LEFT JOIN inventory i ON i.tenant_id=m.tenant_id AND i.warehouse_id=m.warehouse_id AND i.material_id=m.material_id WHERE i.id IS NULL
UNION ALL SELECT 'issue_cost_flow', COUNT(*) FROM issues h WHERE h.amount <> COALESCE((SELECT SUM(m.amount) FROM stock_movements m WHERE m.issue_id=h.id AND m.kind='ISSUE'),0)
UNION ALL SELECT 'payable_receipt_total', COUNT(*) FROM payables p WHERE p.amount <> COALESCE((SELECT SUM(r.amount) FROM receipts r WHERE r.order_id=p.order_id),0)-COALESCE((SELECT SUM(r.amount) FROM purchase_returns r WHERE r.order_id=p.order_id),0)
UNION ALL SELECT 'paid_payment_total', COUNT(*) FROM payables p WHERE p.paid_amount <> COALESCE((SELECT SUM(t.amount) FROM payments t WHERE t.payable_id=p.id),0)-COALESCE((SELECT SUM(r.amount) FROM supplier_refunds r WHERE r.payable_id=p.id),0) OR p.paid_amount<0 OR p.amount<0
UNION ALL SELECT 'receipt_has_payable', COUNT(*) FROM receipts r LEFT JOIN payables p ON p.order_id=r.order_id WHERE p.id IS NULL
UNION ALL SELECT 'payment_application_link', COUNT(*) FROM payment_applications a LEFT JOIN payments p ON p.id=a.payment_id WHERE a.status='PAID' AND (p.id IS NULL OR p.amount<>a.amount OR p.payable_id<>a.payable_id)
UNION ALL SELECT 'payment_application_reservations', COUNT(*) FROM payables p WHERE COALESCE((SELECT SUM(a.amount) FROM payment_applications a WHERE a.payable_id=p.id AND a.status IN ('PENDING','APPROVED')),0)>GREATEST(p.amount-p.paid_amount,0)
UNION ALL SELECT 'payment_application_approved_reviewer', COUNT(*) FROM payment_applications a WHERE a.status='APPROVED' AND (a.reviewer_id IS NULL OR a.reviewer_id=a.applicant_id OR a.reviewed_at IS NULL)
UNION ALL SELECT 'payment_application_execution_separation', COUNT(*) FROM payment_applications a JOIN payments p ON p.id=a.payment_id WHERE a.reviewer_id IS NOT NULL AND a.status='PAID' AND a.reviewer_id=p.operator_id
UNION ALL SELECT 'payment_application_terminal_link', COUNT(*) FROM payment_applications a WHERE a.status<>'PAID' AND a.payment_id IS NOT NULL
UNION ALL SELECT 'order_closed_quantity',COUNT(*) FROM order_items i WHERE i.closed_quantity<0 OR i.received_quantity+i.closed_quantity>i.quantity OR i.closed_amount<0
UNION ALL SELECT 'order_closed_amount',COUNT(*) FROM purchase_orders o WHERE o.closed_amount<>COALESCE((SELECT SUM(i.closed_amount) FROM order_items i WHERE i.order_id=o.id),0) OR o.closed_amount>o.total_amount
UNION ALL SELECT 'closed_order_has_remaining',COUNT(*) FROM purchase_orders o JOIN order_items i ON i.order_id=o.id WHERE o.status='CLOSED' AND i.received_quantity+i.closed_quantity<>i.quantity
UNION ALL SELECT 'replacement_source_link',COUNT(*) FROM purchase_requests r LEFT JOIN purchase_orders o ON o.id=r.source_order_id WHERE r.source_order_id IS NOT NULL AND (o.id IS NULL OR o.replacement_request_id<>r.id OR o.replacement_request_id IS NULL)
UNION ALL SELECT 'issue_return_line_total',COUNT(*) FROM issue_returns r WHERE r.amount<>COALESCE((SELECT SUM(i.amount) FROM issue_return_items i WHERE i.return_id=r.id),0)
UNION ALL SELECT 'issue_return_source_limit',COUNT(*) FROM stock_movements m WHERE m.kind='ISSUE' AND (COALESCE((SELECT SUM(i.quantity) FROM issue_return_items i WHERE i.source_movement_id=m.id),0)>-m.quantity OR COALESCE((SELECT SUM(i.amount) FROM issue_return_items i WHERE i.source_movement_id=m.id),0)>m.amount)
UNION ALL SELECT 'issue_return_stock_flow',COUNT(*) FROM issue_returns r WHERE r.amount<>COALESCE((SELECT SUM(m.amount) FROM stock_movements m WHERE m.issue_return_id=r.id AND m.kind='ISSUE_RETURN'),0)
UNION ALL SELECT 'purchase_return_line_totals',COUNT(*) FROM purchase_returns r WHERE r.amount<>COALESCE((SELECT SUM(i.amount) FROM purchase_return_items i WHERE i.return_id=r.id),0) OR r.stock_amount<>COALESCE((SELECT SUM(i.stock_amount) FROM purchase_return_items i WHERE i.return_id=r.id),0) OR r.variance_amount<>r.stock_amount-r.amount
UNION ALL SELECT 'purchase_return_source_limit',COUNT(*) FROM receipt_items r WHERE COALESCE((SELECT SUM(i.quantity) FROM purchase_return_items i WHERE i.receipt_item_id=r.id),0)>r.quantity OR COALESCE((SELECT SUM(i.amount) FROM purchase_return_items i WHERE i.receipt_item_id=r.id),0)>r.amount
UNION ALL SELECT 'purchase_return_stock_flow',COUNT(*) FROM purchase_returns r WHERE r.stock_amount<>COALESCE((SELECT SUM(m.amount) FROM stock_movements m WHERE m.purchase_return_id=r.id AND m.kind='PURCHASE_RETURN'),0)
UNION ALL SELECT 'purchase_return_variance_cost',COUNT(*) FROM purchase_returns r LEFT JOIN costs c ON c.id=r.cost_id WHERE (r.variance_amount<>0 AND (c.id IS NULL OR c.amount<>r.variance_amount OR c.project_id<>r.project_id OR c.category<>'RETURN_VARIANCE')) OR (r.variance_amount=0 AND r.cost_id IS NOT NULL)
UNION ALL SELECT 'supplier_refund_limits',COUNT(*) FROM payables p WHERE COALESCE((SELECT SUM(r.amount) FROM supplier_refunds r WHERE r.payable_id=p.id),0)>COALESCE((SELECT SUM(t.amount) FROM payments t WHERE t.payable_id=p.id),0) OR p.paid_amount>COALESCE((SELECT SUM(r.amount) FROM receipts r WHERE r.order_id=p.order_id),0)
UNION ALL SELECT 'stocktake_independent_review',COUNT(*) FROM stocktakes h WHERE h.status='APPROVED' AND (h.reviewer_id IS NULL OR h.reviewer_id=h.applicant_id OR h.reviewed_at IS NULL)
UNION ALL SELECT 'stocktake_effective_flows',COUNT(*) FROM stocktake_items i JOIN stocktakes h ON h.id=i.stocktake_id WHERE (h.status='APPROVED' AND ((i.difference_quantity<>0 AND (SELECT COUNT(*) FROM stock_movements m WHERE m.stocktake_item_id=i.id)<>1) OR (i.difference_quantity=0 AND EXISTS(SELECT 1 FROM stock_movements m WHERE m.stocktake_item_id=i.id)))) OR (h.status<>'APPROVED' AND EXISTS(SELECT 1 FROM stock_movements m WHERE m.stocktake_item_id=i.id))
UNION ALL SELECT 'stocktake_quantity_amount_link',COUNT(*) FROM stock_movements m JOIN stocktake_items i ON i.id=m.stocktake_item_id WHERE m.project_id IS NOT NULL OR m.stocktake_id<>i.stocktake_id OR m.material_id<>i.material_id OR m.quantity<>i.difference_quantity OR m.amount<>ABS(i.adjustment_amount) OR m.kind<>CASE WHEN i.difference_quantity>0 THEN 'STOCKTAKE_GAIN' ELSE 'STOCKTAKE_LOSS' END
UNION ALL SELECT 'stocktake_snapshot_difference',COUNT(*) FROM stocktake_items i WHERE i.counted_quantity-i.snapshot_quantity<>i.difference_quantity OR i.counted_quantity<0
UNION ALL SELECT 'stocktake_correction_source',COUNT(*) FROM stocktakes h JOIN stocktakes o ON o.id=h.correction_of WHERE o.status<>'APPROVED' OR h.warehouse_id<>o.warehouse_id
UNION ALL SELECT 'plan_total_limit',COUNT(*) FROM contracts c WHERE COALESCE((SELECT SUM(s.amount) FROM contract_payment_stages s WHERE s.contract_id=c.id),0)>c.amount
UNION ALL SELECT 'allocation_source_contract',COUNT(*) FROM contract_payment_allocations l JOIN contracts c ON c.id=l.contract_id JOIN contract_payment_stages s ON s.id=l.stage_id LEFT JOIN payments t ON t.id=l.payment_id LEFT JOIN supplier_refunds r ON r.id=l.refund_id LEFT JOIN payables p ON p.id=COALESCE(t.payable_id,r.payable_id) WHERE s.contract_id<>c.id OR p.order_id<>c.order_id OR (l.payment_id IS NULL AND l.refund_id IS NULL) OR (l.payment_id IS NOT NULL AND l.refund_id IS NOT NULL)
UNION ALL SELECT 'allocation_payment_limit',COUNT(*) FROM payments p WHERE COALESCE((SELECT SUM(l.amount) FROM contract_payment_allocations l WHERE l.payment_id=p.id AND l.voided=FALSE),0)>p.amount
UNION ALL SELECT 'allocation_refund_limit',COUNT(*) FROM supplier_refunds r WHERE COALESCE((SELECT SUM(l.amount) FROM contract_payment_allocations l WHERE l.refund_id=r.id AND l.voided=FALSE),0)>r.amount
UNION ALL SELECT 'allocation_stage_net',COUNT(*) FROM contract_payment_stages s WHERE COALESCE((SELECT SUM(CASE WHEN l.payment_id IS NOT NULL THEN l.amount ELSE -l.amount END) FROM contract_payment_allocations l WHERE l.stage_id=s.id AND l.voided=FALSE),0)<0 OR COALESCE((SELECT SUM(CASE WHEN l.payment_id IS NOT NULL THEN l.amount ELSE -l.amount END) FROM contract_payment_allocations l WHERE l.stage_id=s.id AND l.voided=FALSE),0)>s.amount
UNION ALL SELECT 'issue_source_matching',COUNT(*) FROM stock_movements m JOIN order_items i ON i.id=m.source_order_item_id JOIN purchase_orders o ON o.id=i.order_id WHERE m.material_id<>i.material_id OR m.project_id<>o.project_id;
